import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.B9qR_F1m.js";const a="/bilder/intel.jpg",b=JSON.parse('{"title":"Intel","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/intel.md","filePath":"bereiche/intel.md"}'),s={name:"bereiche/intel.md"};function l(d,e,o,g,h,u){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="intel" tabindex="-1">Intel <a class="header-anchor" href="#intel" aria-label="Permalink to &quot;Intel&quot;">​</a></h1><p><strong>Keine God-View.</strong> In einer echten Staffel weiß nicht jeder Pilot alles. In Shardwing auch nicht: Alle SAM-Stellungen der Mission sind zuerst <strong>verborgen</strong>. Erst wenn du sie freigibst, tauchen sie auf – auf der Karte der Piloten, in ihrer Cartridge, auf der Lineup Card und auf Wunsch in F10.</p><p><img src="'+a+'" alt="Bereich Intel mit freigegebenen (rot) und verborgenen (grau) Stellungen, eine SA-10 ausgewählt" loading="lazy"></p><h2 id="die-drei-zustande" tabindex="-1">Die drei Zustände <a class="header-anchor" href="#die-drei-zustande" aria-label="Permalink to &quot;Die drei Zustände&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Farbe</th><th>Zustand</th><th>Wer sieht es</th></tr></thead><tbody><tr><td><span class="dot grey"></span> grau</td><td><strong>Verborgen</strong></td><td>nur der Mission Designer</td></tr><tr><td><span class="dot orange"></span> orange</td><td><strong>Bestimmte Flights</strong></td><td>nur die ausgewählten Flights</td></tr><tr><td><span class="dot red"></span> rot</td><td><strong>Alle Flights</strong></td><td>alle Piloten</td></tr></tbody></table><p>Oben zählt Shardwing mit: <em>7 alle · 0 einzelne · 0 verborgen</em>.</p><h2 id="freigeben" tabindex="-1">Freigeben <a class="header-anchor" href="#freigeben" aria-label="Permalink to &quot;Freigeben&quot;">​</a></h2><ul><li><strong>Einzeln:</strong> Stellung links oder auf der Karte anklicken, im Panel den Zustand wählen. Bei <em>Bestimmte Flights</em> hakst du die Flights an.</li><li><strong>Alle auf einmal:</strong> <strong>Alle aus Mission freigeben</strong> bzw. <strong>Alle verbergen</strong>.</li><li><strong>Filtern:</strong> Über der Liste zwischen <em>Alle</em>, <em>Verborgen</em> und <em>Freigegeben</em> wechseln.</li></ul><p>Pro Stellung stellst du ein:</p><ul><li><strong>System</strong> (SA-2 … SA-19, Patriot, Hawk, AAA … oder <em>Custom</em>) und <strong>Reichweite</strong> in NM. Shardwing erkennt das System aus den Einheiten der Gruppe und schlägt eine Reichweite vor.</li><li><strong>Position</strong> – ziehen auf der Karte oder Koordinate eingeben.</li><li><strong>Auf der F10-Karte zeigen</strong> (Ring, Dreieck, Name) – nur bei <em>Alle Flights</em>, damit F10 nichts verrät.</li></ul><div class="info custom-block"><p class="custom-block-title">Woher die Reichweiten kommen</p><p>Die vorgeschlagenen Ringe sind die, die der Mission Editor für den Typ auf einer Cartridge zeichnet (z. B. SA-6 25 km, SA-10 120 km). Für Systeme, die es dort nicht gibt (MANPADS, ZU-23 …), sind es grobe Planungswerte. Passe sie an, wenn eure Gruppe andere Faustwerte nutzt.</p></div><h2 id="eigene-threats" tabindex="-1">Eigene Threats <a class="header-anchor" href="#eigene-threats" aria-label="Permalink to &quot;Eigene Threats&quot;">​</a></h2><p>Nicht jede Bedrohung steht als Einheit in der Mission – etwa eine <em>vermutete</em> SA-6 oder ein MANPADS-Gebiet. Unter <strong>Eigener Threat</strong> wählst du System und Reichweite und setzt ihn mit <strong>+ Auf der Karte</strong> per Klick.</p><p>Beim gemeinsamen Planen dürfen auch Flight Leads eigene Threats setzen (wenn freigegeben). Die sieht dann nur ihr Flight und der Designer.</p><h2 id="eigene-luftabwehr" tabindex="-1">Eigene Luftabwehr <a class="header-anchor" href="#eigene-luftabwehr" aria-label="Permalink to &quot;Eigene Luftabwehr&quot;">​</a></h2><p>Blaue SAM-Stellungen der Mission stehen unter <strong>Eigene Luftabwehr</strong>. Freigegeben sehen die Piloten sie auf Karte, Kneeboard und F10 – damit sie wissen, wo sie geschützt sind. Sie landen <strong>nie</strong> als Threat in der Cartridge oder in Threat-Tabellen.</p><h2 id="iads-ubersicht" tabindex="-1">IADS-Übersicht <a class="header-anchor" href="#iads-ubersicht" aria-label="Permalink to &quot;IADS-Übersicht&quot;">​</a></h2><p>Der Schalter <strong>IADS-Übersicht auf der Karte</strong> zeigt das gegnerische Netz aus dem <a href="/bereiche/iads">IADS-Werkzeug</a> mit allen Verbindungen. Das ist nur für dich als Designer – Piloten sehen das Netz nie.</p><h2 id="wohin-freigegebene-threats-gehen" tabindex="-1">Wohin freigegebene Threats gehen <a class="header-anchor" href="#wohin-freigegebene-threats-gehen" aria-label="Permalink to &quot;Wohin freigegebene Threats gehen&quot;">​</a></h2><ul><li><strong>Karte</strong> des Flights (rote Raute mit Ring)</li><li><strong>Cartridge</strong>: als Threat-Punkte (F-16: STPT 56–70, F/A-18: MEZ-Ringe) – nur die, die der Flight kennen darf</li><li><strong>Lineup Card</strong> und Routenkarte</li><li><strong>Paket-Kneeboards</strong> wie <em>Bedrohungen</em> und <em>Lagekarte</em> – nur Intel für alle</li><li><strong>F10-Karte</strong>, wenn eingeschaltet</li></ul><div class="warning custom-block"><p class="custom-block-title">Threats nur für einen Flight</p><p>Kneeboards gelten in DCS pro Flugzeugtyp. Bettest du die Lineup Card eines Flights mit exklusiven Threats in die .miz ein, sieht jeder andere Flight desselben Typs sie im Kneeboard. Shardwing warnt in der <a href="/bereiche/uebersicht">Übersicht</a> davor. Besser: Unterlagen dieses Flights per <a href="/dcs/speichern#export">Export</a> verteilen.</p></div>',21)])])}const m=t(s,[["render",l]]);export{b as __pageData,m as default};
